/**
 * @name Detailed pickle.load analysis
 * @description Analyze pickle.load usage context and data source
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-load-analysis
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PickleAnalysisConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Check for remote sources AND local file reads
    source instanceof RemoteFlowSource or
    exists(FileSystemAccess fa | 
      fa = API::moduleImport("builtins").getMember("open").getACall() and
      source = fa.getAPathArgument()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleAnalysisFlow = TaintTracking::Global<PickleAnalysisConfig>;
import PickleAnalysisFlow::PathGraph

from PickleAnalysisFlow::PathNode source, PickleAnalysisFlow::PathNode sink
where PickleAnalysisFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data reaches unsafe pickle deserialization from $@.", source.getNode(), "input source"

/**
 * @name Path traversal in file operations
 * @description Using file paths derived from untrusted input without validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // File open operations
      call = API::moduleImport(["builtins", "__builtin__"]).getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // os.path operations
      call = API::moduleImport("os").getMember(["path.join", "path.abspath", "path.realpath"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Path operations
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

